function plan(api) {
  api.terrain('plain', { amplitude: 1.8, roughness: 0.22, seed: api.seed });

  const sites = [[0, -3], [-5, -5], [5, -2]];
  const readings = sites.map(function (p) {
    const offsets = [[0, 0], [-14, -18], [14, -18], [-14, 20], [14, 20]];
    const samples = offsets.map(function (o) {
      return api.environmentSample([p[0] + o[0], p[1] + o[1]]);
    });
    const heights = samples.map(function (s) { return s.height; });
    return {
      point: p,
      height: samples[0].height,
      relief: Math.max.apply(null, heights) - Math.min.apply(null, heights),
      slope: samples.reduce(function (v, s) { return v + s.slope; }, 0)
    };
  });
  readings.sort(function (a, b) {
    return (a.relief + a.slope * 0.15) - (b.relief + b.slope * 0.15);
  });
  const center = readings[0].point;
  const initialHeight = readings[0].height;

  function p(x, z) { return [center[0] + x, center[1] + z]; }
  function region(points) {
    return { kind: 'polygon', points: points.map(function (q) { return p(q[0], q[1]); }) };
  }

  // Grade only the church and its immediate apron.
  api.sculptTerrain({
    mode: 'flatten', point: p(0, -1), radius: 29,
    targetHeight: initialHeight, strength: 1
  });
  const base = api.environmentSample(p(0, 0)).height;
  api.surface({
    id: 'cathedral-apron', surface: 'paving', material: 'garden-stone',
    region: region([[-21, -26], [21, -26], [21, 24], [-21, 24]]),
    intensity: 1
  });

  function asset(key, name, dimensions, prompt) {
    api.requireAsset({ key: key, name: name, dimensions: dimensions, role: 'structure', prompt: prompt });
  }

  asset('aisle', '侧廊墙段', [6, 11, 3],
    'Gothic cathedral limestone side aisle wall bay. Y up, X spans exactly 6m between flush joining faces; Z+ faces outside. Solid masonry lower wall, one tall recessed pointed stained glass window with stone tracery, attached projecting buttress and small crocketed pinnacle, weathered pale gray stone. Top cornice at 10m, parapet to 11m. No corner returns, no floor or roof across adjoining bays.');
  asset('clerestory', '高窗墙段', [6, 9, 1.2],
    'Upper clerestory wall bay of a monumental Gothic limestone cathedral. X span exactly 6m with flush joining ends, Z+ exterior. Two extremely tall lancet stained glass windows beneath pointed stone tracery, blind triforium band at base, rich cornice at top. Vertical 9m wall, no roof, no side returns. Weathered pale limestone.');
  asset('buttress', '飞扶壁', [1.6, 15, 6],
    'One structural Gothic flying buttress assembly. Y up, local Z+ outward from nave. A narrow X-width of 1.6m; inner joining face at Z=-3 reaches 15m high against the clerestory, two pierced sloping stone arch struts descend toward a solid outer pier at Z=+3. Outer pier rooted on ground with a crocketed pinnacle. Open space beneath flying arches. Pale weathered limestone, carved gargoyle.');
  asset('roof', '中殿屋顶段', [12, 5, 6],
    'One 6m longitudinal segment of steep Gothic nave roof, span axis Z. Exactly 12m across X, 5m ridge rise above open bottom, dark blue gray slate, lead ribs, delicate ridge cresting. Open joining ends at Z=-3 and Z=+3, no gable walls, seamless adjoining segments. Y up.');
  asset('aisle-roof', '侧廊斜屋顶', [3.5, 2, 6],
    'One longitudinal 6m Gothic side aisle lean-to roof segment. X width 3.5m, Z joining ends open and flush. Highest at local X=-1.75, lowest at X=+1.75, gray blue slate over limestone eaves. Y up. No enclosing walls.');
  asset('portal', '尖拱门廊', [6, 11, 3],
    'Gothic cathedral entrance portal bay, exactly 6m X span, flush joining sides, Z+ front. Deep splayed pointed arch filled with carved archivolts, sculpted saints in niches and ornate tympanum. Large closed dark oak double doors at ground level, bronze hinges, modest flush threshold. Pale limestone facade with crocketed pointed canopy rising to 11m. No side returns.');
  asset('rose', '玫瑰窗立面', [18, 9, 2],
    'Unified upper entrance facade of Gothic stone cathedral, 18m wide X, 9m high, Z+ front. Huge circular stained glass rose window centered in deeply carved radial limestone tracery, blue ruby and gold glass, flanking slender blind arcades. Flush lower edge and side joining faces, no roof, no doorway. Finely weathered pale limestone.');
  asset('gable', '山墙', [12, 5, 1.5],
    'Triangular Gothic nave end gable, 12m X width and 5m rise, Z+ exterior. Pale limestone carved blind tracery, small central lancet, crocketed diagonal coping and stone cross at apex. Flat bottom, roof joining behind. No rectangular lower wall.');
  asset('tower-base', '钟楼基座', [7, 11, 7],
    'Square Gothic cathedral tower lower story, 7m by 7m footprint, 11m tall, Y up and Z+ front. Pale limestone masonry, corner buttresses, narrow stained glass lancets, recessed pointed oak entrance on front at ground level. Level open joining top for a stacked belfry, no roof. Rich carved stringcourse.');
  asset('tower-stage', '钟楼层段', [7, 10, 7],
    'Stackable square Gothic cathedral belfry story, exact 7m square and 10m height. Flat bottom and level top joining planes, no roof. Four faces have paired deep pointed louver openings, sculpted tracery, corner engaged shafts, continuous horizontal stone cornice. Pale weathered limestone. Y up, Z+ principal front.');
  asset('spire', '哥特尖塔', [7.5, 16, 7.5],
    'Crowning roof for a square Gothic cathedral bell tower. 7.5m square stone parapet base, four slender corner pinnacles surrounding a soaring octagonal dark slate spire, lucarnes, fine lead seams and metal cross. Total height 16m from flat base. Pale limestone and charcoal blue slate. Y up.');
  asset('end-wall', '后殿墙段', [6, 20, 1.5],
    'Gothic cathedral tall end enclosure bay, X span 6m with flat joining faces. Z+ faces exterior. Pale limestone wall with deeply recessed slender stained glass lancets in two registers, tracery, engaged boundary pilasters and a stone cornice. Total height 20m, no roof, no doorway.');
  asset('crossing-roof', '交叉穹顶', [12, 13, 12],
    'Gothic cathedral crossing roof crown. Square open-bottom 12m by 12m footprint, four intersecting slate roof slopes rising 5m, with slender octagonal limestone lantern and lead fleche rising a further 8m. Four open roof joining faces match 12m wide adjacent gabled roofs. Carved pierced lantern windows and gilded finial. Y up, Z+ front.');
  asset('bench', '石长椅', [3, 1.1, 0.9],
    'Standalone weathered limestone garden bench with carved Gothic trefoil supports and simple back, 3m wide, Y up, Z+ seating front.');
  api.requireAsset({
    key: 'tree', name: '古柏', dimensions: [4, 13, 4], role: 'environment',
    prompt: 'One mature narrow cypress tree, dark green dense layered foliage, irregular tapering crown and visible weathered trunk, Y up.'
  });

  function put(key, x, z, y, yaw, dims) {
    return api.place({
      assetId: api.asset(key), position: [center[0] + x, y, center[1] + z],
      rotationY: yaw || 0, dimensions: dims, terrain: false
    });
  }
  function bay(key, a, b, elevation, dimensions, target) {
    api.placeBetween({
      assetId: api.asset(key), start: p(a[0], a[1]), end: p(b[0], b[1]),
      dimensions: dimensions, spanAxis: 'x', terrain: false, elevation: elevation,
      frontTarget: p(target[0], target[1])
    });
  }

  const footprint = region([
    [-16, 22], [16, 22], [16, 13], [10, 13], [10, -2],
    [20, -2], [20, -14], [10, -14], [10, -21],
    [-10, -21], [-10, -14], [-20, -14], [-20, -2],
    [-10, -2], [-10, 13], [-16, 13]
  ]);
  api.surface({ id: 'church-ground', surface: 'rock', region: footprint, intensity: 1 });
  api.foundation({
    position: p(0, -1), width: 21, depth: 42,
    shape: 'rounded-rectangle', top: 'level', maxThickness: 3,
    material: 'limestone'
  });
  api.foundation({
    position: p(0, -8), width: 41, depth: 13,
    shape: 'rounded-rectangle', top: 'level', maxThickness: 3,
    material: 'limestone'
  });

  // Six longitudinal bays; the two crossing bays remain open into the transepts.
  for (let i = 0; i < 6; i++) {
    const z0 = -20 + 6 * i;
    const z1 = z0 + 6;
    const crossing = i === 1 || i === 2;
    if (!crossing) {
      for (let side = -1; side <= 1; side += 2) {
        bay('aisle', [side * 9, z0], [side * 9, z1], base, [6, 11, 3], [side * 35, (z0 + z1) / 2]);
        bay('clerestory', [side * 6, z0], [side * 6, z1], base + 11, [6, 9, 1.2], [side * 35, (z0 + z1) / 2]);
        put('aisle-roof', side * 8, (z0 + z1) / 2, base + 10, side === 1 ? 0 : Math.PI);
        put('buttress', side * 10, (z0 + z1) / 2, base, side * Math.PI / 2);
      }
      put('roof', 0, (z0 + z1) / 2, base + 20, 0);
    }
  }

  // Short transverse arms share the crossing floor and roof heights.
  for (let side = -1; side <= 1; side += 2) {
    for (let j = 0; j < 2; j++) {
      const xa = side * (6 + j * 6);
      const xb = side * (12 + j * 6);
      for (let edge = 0; edge < 2; edge++) {
        const z = edge === 0 ? -14 : -2;
        bay('aisle', [xa, z], [xb, z], base, [6, 11, 3], [(xa + xb) / 2, edge === 0 ? -40 : 35]);
        bay('clerestory', [xa, z], [xb, z], base + 11, [6, 9, 1.2], [(xa + xb) / 2, edge === 0 ? -40 : 35]);
      }
      put('roof', (xa + xb) / 2, -8, base + 20, Math.PI / 2);
    }
    for (let j = 0; j < 2; j++) {
      bay('end-wall', [side * 18, -14 + j * 6], [side * 18, -8 + j * 6],
        base, [6, 20, 1.5], [side * 40, -8]);
    }
    put('gable', side * 18, -8, base + 20, side * Math.PI / 2);
  }
  put('crossing-roof', 0, -8, base + 20, 0);

  for (let j = 0; j < 3; j++) {
    bay('end-wall', [-9 + j * 6, -20], [-3 + j * 6, -20], base, [6, 20, 1.5], [0, -40]);
    bay('portal', [-9 + j * 6, 16], [-3 + j * 6, 16], base, [6, 11, 3], [0, 40]);
  }
  put('gable', 0, -20, base + 20, Math.PI);
  put('rose', 0, 16, base + 11, 0);
  put('gable', 0, 16, base + 20, 0);

  for (let side = -1; side <= 1; side += 2) {
    const x = side * 12.5;
    api.sculptTerrain({ mode: 'flatten', point: p(x, 17), radius: 5.5, targetHeight: base, strength: 1 });
    const towerGround = api.environmentSample(p(x, 17)).height;
    const tower = put('tower-base', x, 17, towerGround, 0);
    api.foundation({ under: [tower], top: 'level', maxThickness: 3, material: 'limestone' });
    put('tower-stage', x, 17, towerGround + 11, 0);
    put('tower-stage', x, 17, towerGround + 21, 0);
    put('spire', x, 17, towerGround + 31, 0);
  }

  api.surface({
    id: 'forecourt', surface: 'paving', material: 'cobblestone',
    region: region([[-20, 21], [20, 21], [23, 32], [14, 37], [-14, 37], [-23, 32]]),
    intensity: 1
  });
  const approachEnd = p(0, 41);
  const approachHeight = api.environmentSample(approachEnd).height;
  api.rampTerrain({
    start: p(0, 18), end: approachEnd, width: 13,
    startHeight: base, endHeight: approachHeight, softness: 0.7, strength: 1
  });
  api.route({
    id: 'processional-way', points: [p(0, 43), p(0, 34), p(0, 24), p(0, 18)],
    width: 9, curve: 'polyline', surface: 'paving', material: 'garden-stone'
  });
  for (let side = -1; side <= 1; side += 2) {
    api.route({
      id: 'church-walk-' + side,
      points: [p(0, 31), p(side * 22, 27), p(side * 24, 8), p(side * 25, -17), p(side * 15, -26), p(0, -27)],
      width: 2.5, curve: 'catmull-rom', surface: 'paving', material: 'gravel'
    });
    api.route({
      id: 'tower-access-' + side,
      points: [p(side * 12.5, 27), p(side * 12.5, 21)],
      width: 3, surface: 'paving', material: 'garden-stone'
    });
    for (let j = 0; j < 3; j++) {
      api.place({
        assetId: api.asset('bench'), position: p(side * 18, 25 + j * 3.5),
        rotationY: -side * Math.PI / 2
      });
    }
  }

  api.grass('cathedral-meadow', {
    kind: 'polygon', points: [[-47, -47], [47, -47], [47, 47], [-47, 47]]
  }, {
    preset: 'meadow', density: 0.75, variation: 0.3, height: 0.28,
    mix: { short: 0.83, tall: 0.13, flowers: 0.04 },
    habitat: { excludeSurfaces: ['paving', 'rock'], maxSlope: 0.6 }
  });
  api.grass('rear-wildflowers', { kind: 'circle', center: p(0, -34), radius: 10 }, {
    preset: 'meadow', density: 0.85, variation: 0.45, height: 0.48,
    mix: { short: 0.4, tall: 0.4, flowers: 0.2 }
  });

  const trees = api.sampleProbabilityField({
    bounds: { minX: -43, maxX: 43, minZ: -43, maxZ: 39 },
    maxPoints: 24, candidates: 220, minDistance: 6,
    seed: api.seed + 11
  }, function (q) {
    const x = q[0] - center[0];
    const z = q[1] - center[1];
    if (Math.abs(x) < 29 && z > -30) return 0;
    if (z > 24 && Math.abs(x) < 34) return 0;
    const s = api.environmentSample(q);
    return s.slope < 0.65 ? 0.65 : 0;
  });
  trees.forEach(function (q, i) {
    const scale = 0.85 + (i % 4) * 0.08;
    api.place({
      assetId: api.asset('tree'), position: q, rotationY: i * 1.73,
      dimensions: [4 * scale, 13 * scale, 4 * scale]
    });
  });
  api.spawn(p(0, 40), 180);
}

function plan(api) {
  api.terrain('hills', { amplitude: 5, roughness: 0.32, seed: 2876401359 });
  api.modifyTerrain({
    modifier: 'ridge',
    region: { kind: 'path', points: [[-38, -36], [0, -32], [39, -39]], width: 32 },
    amplitude: 10,
    softness: 0.85
  });
  api.modifyTerrain({
    modifier: 'terrace',
    region: { kind: 'circle', center: [0, 24], radius: 24 },
    amplitude: 1.5,
    softness: 0.8
  });

  function sample(p) { return api.environmentSample(p); }
  function height(p) { return sample(p).height; }
  function distance(a, b) { return Math.hypot(a[0] - b[0], a[1] - b[1]); }
  function yaw(a, b) { return Math.atan2(b[0] - a[0], b[1] - a[1]); }
  function declare(key, name, dimensions, prompt, role) {
    api.requireAsset({ key: key, name: name, dimensions: dimensions, prompt: prompt, role: role || 'structure' });
  }
  function place(key, p, dimensions, rotation) {
    return api.place({ assetId: api.asset(key), position: p, dimensions: dimensions, rotationY: rotation || 0 });
  }

  const alternatives = [[-5, 23], [5, 25], [-8, 29]].map(function(p) {
    const observations = [p, [p[0] - 10, p[1]], [p[0] + 10, p[1]], [p[0], p[1] - 8]].map(sample);
    const hs = observations.map(function(s) { return s.height; });
    return { p: p, spread: Math.max.apply(null, hs) - Math.min.apply(null, hs), slope: observations[0].slope };
  });
  alternatives.sort(function(a, b) { return a.spread - b.spread; });
  const center = alternatives[0].p;
  const cx = center[0], cz = center[1];
  const base = height(center);
  api.sculptTerrain({ mode: 'flatten', point: center, radius: 13, targetHeight: base, strength: 0.95 });
  const courtHeight = height(center);

  api.surface({
    id: 'alpine-ground',
    surface: 'rock',
    region: { kind: 'polygon', points: [[-48, -48], [48, -48], [48, 48], [-48, 48]] },
    intensity: 0.85
  });

  declare('snow', '积雪地表', [16, 1.2, 16],
    'A broad continuous opaque ivory-white alpine snow blanket, irregular feathered perimeter, gently undulating upper surface and deep downward skirts burying underlying ground. No rocks, plants or objects. Fine blue shaded wind ripples, mostly smooth white packed snow. Y up, Z front.', 'environment');
  declare('hotel', '木屋酒店', [12, 11, 10],
    'Complete three-storey alpine timber chalet hotel, Y up Z+ entrance. Heavy stone ground floor, honey brown log upper floors, steep dark timber gable roof carrying thick white snow, projecting eaves and icicles. Fixed warm amber windows, carved continuous balconies, central front door at ground level with sheltered porch. Chimneys and red shutters. Entire building including roof and all fixed details.');
  declare('lodge', '主会馆', [18, 13, 12],
    'Complete large simple rectangular alpine lodge, Y up Z+ front. Stone ground storey and three timber storeys under one steep snow-covered gabled roof. Tall central glazed front entrance at ground level, sheltered terrace within footprint, warm windows, integral wood balconies, stout stone chimney and small central clock under the gable. Rich dark timber and cream stone.');
  declare('rental', '滑雪服务屋', [10, 5, 7],
    'Complete single-storey ski rental chalet, Y up Z+ entrance. Snow-covered pitched timber roof, wide glazed front doors at ground level, warm shop windows, attached racks of colorful skis beneath front eaves, timber walls on a stone plinth.');
  declare('station', '缆车站', [8, 7, 10],
    'Alpine gondola terminal, Y up Z+ uphill cable direction. Snow-covered timber and steel shelter, open axial gondola passage along local Z, boarding platform at ground level accessible from both X sides, overhead return wheel centered 5.5 meters above base. Front and rear axial openings, dark machinery, red gondola docked inside, stone base.');
  declare('tower', '缆车支架', [4.8, 9, 2.5],
    'Ski gondola support pylon, Y up Z+ cable travel. Galvanized tapered steel mast on concrete foot, transverse X crossarm with sheave rollers at X=-1.5 and X=1.5, roller contact height 8.5m above bottom, maintenance ladder and safety cage.');
  declare('cable', '架空钢索', [0.08, 1, 10],
    'One straight taut dark steel gondola cable rising along local Z. Y up. Rear endpoint at local Z=-5 Y=0, front endpoint at Z=5 Y=1; local X centered. Thin consistent round cable, no posts. Requested dimensions scale the endpoint rise and longitudinal span.', 'environment');
  declare('cab', '红色吊厢', [2.2, 3.8, 2.3],
    'Single red enclosed alpine gondola cabin with panoramic smoked glass windows, visible seats, curved red lower body and black suspension hanger extending above roof. Y up Z+ travel. Bottom of cabin is object base; hanger attachment is at top, 3.8m above base.', 'environment');
  declare('pine', '雪松', [5, 10, 5],
    'One tall alpine spruce, Y up Z front, dark evergreen layered branches heavily laden with crisp white snow, narrow pointed crown and exposed brown trunk. Natural asymmetric silhouette.', 'environment');
  declare('marker', '雪道标杆', [0.35, 2.3, 0.35],
    'One slender red alpine ski piste marker pole with a blue circular trail marker near its top, snow embedded foot, Y up Z front.', 'environment');
  declare('sign', '导览牌', [3.2, 2.7, 0.6],
    'Timber ski resort wayfinding board on two wooden posts, Y up Z+ readable front, small snowy pitched cap, stylized blue and red ski trail diagram and clear directional arrows, no ground slab.', 'environment');
  declare('bench', '休憩长椅', [3, 1.3, 1],
    'Alpine outdoor timber bench with thick carved backrest, dark iron legs and light snow on the upper back. Clear usable wooden seat. Y up Z+ seating front.', 'environment');

  const snowPoints = api.sampleProbabilityField({
    bounds: { minX: -42, maxX: 42, minZ: -42, maxZ: 42 },
    candidates: 1500, maxPoints: 110, minDistance: 7.7, seed: 2876401360
  }, function() { return 1; });
  snowPoints.forEach(function(p, i) {
    place('snow', [p[0], height(p) - 0.65, p[1]], [17, 1.2, 17], (i % 4) * 0.72);
  });

  const plaza = { kind: 'circle', center: center, radius: 10 };
  api.surface({ id: 'arrival-court', surface: 'paving', material: 'garden-stone', region: plaza });
  const arrival = [[cx + 5, 46], [cx + 6, 39], [cx + 3, cz + 9], center];
  api.route({ id: 'arrival-road', points: arrival, width: 5, curve: 'catmull-rom', surface: 'paving', material: 'cobblestone' });
  api.spawn([cx + 5, 42], 180);

  const occupied = [];
  function building(key, p, dims, access) {
    const original = sample(p);
    api.sculptTerrain({ mode: 'flatten', point: p, radius: Math.max(dims[0], dims[2]) * 0.59, targetHeight: original.height, strength: 0.95 });
    const h = height(p);
    const angle = yaw(p, access);
    const obj = place(key, [p[0], h, p[1]], dims, angle);
    api.foundation({ under: [obj], top: 'level', maxThickness: 4, material: 'stone' });
    const door = [p[0] + Math.sin(angle) * dims[2] / 2, p[1] + Math.cos(angle) * dims[2] / 2];
    api.rampTerrain({ start: access, end: door, width: 3, startHeight: height(access), endHeight: h, softness: 0.8, strength: 1 });
    api.route({ id: 'door-' + occupied.length, points: [access, door], width: 2.8, surface: 'paving', material: 'garden-stone' });
    occupied.push({ p: p, radius: Math.hypot(dims[0], dims[2]) / 2 + 1 });
  }

  building('lodge', [cx, cz - 15], [18, 13, 12], [cx, cz - 6]);
  building('hotel', [cx - 19, cz - 4], [12, 11, 10], [cx - 8, cz - 2]);
  building('hotel', [cx + 19, cz - 3], [12, 11, 10], [cx + 8, cz]);
  building('hotel', [cx - 18, cz + 13], [12, 10, 10], [cx - 7, cz + 7]);
  building('hotel', [cx + 19, cz + 13], [12, 12, 10], [cx + 7, cz + 8]);
  building('rental', [cx - 16, cz - 18], [10, 5, 7], [cx - 13, cz - 10]);

  const loop = [[cx - 8, cz + 8], [cx - 10, cz], [cx - 12, cz - 10], [cx - 13, cz - 23],
    [cx + 12, cz - 23], [cx + 12, cz - 10], [cx + 10, cz], [cx + 8, cz + 8], [cx, cz + 9], [cx - 8, cz + 8]];
  api.route({ id: 'hotel-promenade', points: loop, width: 3, curve: 'catmull-rom', surface: 'paving', material: 'compacted-earth' });
  place('sign', [cx - 3, courtHeight, cz + 3], [3.2, 2.7, 0.6], 0);
  [[-6, 4], [6, 4], [-5, -5], [5, -5]].forEach(function(d) {
    place('bench', [cx + d[0], cz + d[1]], [3, 1.3, 1], d[1] < 0 ? 0 : Math.PI);
  });

  const upperCandidates = [[-25, -37], [-18, -38], [-10, -37]].map(function(p) {
    return { p: p, s: sample(p) };
  });
  upperCandidates.sort(function(a, b) { return b.s.height - a.s.height; });
  const top = upperCandidates[0].p;
  const bottom = [cx - 27, cz - 16];
  [bottom, top].forEach(function(p) {
    const h = height(p);
    api.sculptTerrain({ mode: 'flatten', point: p, radius: 6.5, targetHeight: h, strength: 1 });
    sample(p);
  });
  const liftAngle = yaw(bottom, top);
  const lowH = height(bottom), highH = height(top);
  [bottom, top].forEach(function(p) {
    const obj = place('station', [p[0], height(p), p[1]], [8, 7, 10], liftAngle);
    api.foundation({ under: [obj], top: 'level', maxThickness: 4, material: 'stone' });
    occupied.push({ p: p, radius: 7 });
  });
  api.route({ id: 'lift-access', points: [[cx - 13, cz - 10], [cx - 22, cz - 10], bottom], width: 4, surface: 'paving', material: 'compacted-earth' });

  const nodes = [{ p: bottom, h: lowH + 5.5 }];
  for (let i = 1; i <= 3; i++) {
    const t = i / 4;
    const p = [bottom[0] + (top[0] - bottom[0]) * t, bottom[1] + (top[1] - bottom[1]) * t];
    const ground = height(p);
    const obj = place('tower', [p[0], ground, p[1]], [4.8, 9, 2.5], liftAngle);
    api.foundation({ under: [obj], top: 'level', maxThickness: 2, material: 'concrete' });
    nodes.push({ p: p, h: ground + 8.5 });
  }
  nodes.push({ p: top, h: highH + 5.5 });
  const perpendicular = [Math.cos(liftAngle), -Math.sin(liftAngle)];
  for (let i = 0; i < nodes.length - 1; i++) {
    const a = nodes[i], b = nodes[i + 1];
    [-1.5, 1.5].forEach(function(offset) {
      const pa = [a.p[0] + perpendicular[0] * offset, a.p[1] + perpendicular[1] * offset];
      const pb = [b.p[0] + perpendicular[0] * offset, b.p[1] + perpendicular[1] * offset];
      const lower = a.h <= b.h ? pa : pb;
      const upper = a.h <= b.h ? pb : pa;
      place('cable', [(pa[0] + pb[0]) / 2, Math.min(a.h, b.h), (pa[1] + pb[1]) / 2],
        [0.08, Math.max(0.02, Math.abs(b.h - a.h)), distance(pa, pb)], yaw(lower, upper));
      const t = offset < 0 ? 0.38 : 0.68;
      place('cab', [pa[0] + (pb[0] - pa[0]) * t, a.h + (b.h - a.h) * t - 3.8, pa[1] + (pb[1] - pa[1]) * t],
        [2.2, 3.8, 2.3], liftAngle);
    });
  }

  const pistes = [
    [top, [-4, -31], [14, -25], [28, -14], [30, -2], [cx + 12, cz - 23]],
    [top, [-11, -23], [0, -14], [cx, cz - 24], [cx + 12, cz - 23]]
  ];
  pistes.forEach(function(points, index) {
    const width = index === 0 ? 8 : 6;
    for (let j = 0; j < points.length - 1; j++) {
      const a = points[j], b = points[j + 1];
      const ah = height(a), bh = height(b);
      api.rampTerrain({ start: a, end: b, width: width, startHeight: ah, endHeight: bh, softness: 0.95, strength: 0.85 });
      const length = distance(a, b), angle = yaw(a, b);
      const count = Math.ceil(length / 5);
      for (let k = 0; k < count; k++) {
        const t = (k + 0.5) / count;
        const p = [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
        place('snow', [p[0], height(p) - 0.2, p[1]], [width + 1, 0.45, length / count + 2], angle);
        if (k % 2 === 0) {
          [-1, 1].forEach(function(side) {
            const q = [p[0] + Math.cos(angle) * (width / 2 + 0.5) * side,
              p[1] - Math.sin(angle) * (width / 2 + 0.5) * side];
            place('marker', q, [0.35, 2.3, 0.35], angle);
          });
        }
      }
    }
    api.route({ id: 'ski-piste-' + index, points: points, width: width, curve: 'catmull-rom', surface: 'none' });
  });

  function segmentDistance(p, a, b) {
    const dx = b[0] - a[0], dz = b[1] - a[1];
    const t = Math.max(0, Math.min(1, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dz) / Math.max(0.001, dx * dx + dz * dz)));
    return distance(p, [a[0] + dx * t, a[1] + dz * t]);
  }
  const trees = api.sampleProbabilityField({
    bounds: { minX: -43, maxX: 43, minZ: -43, maxZ: 43 },
    candidates: 1600, maxPoints: 95, minDistance: 4.6,
    cluster: { strength: 0.6, scale: 15, seed: 2876401361 }
  }, function(p) {
    const s = sample(p);
    if (distance(p, center) < 31 || occupied.some(function(o) { return distance(p, o.p) < o.radius + 3; })) return 0;
    if (segmentDistance(p, bottom, top) < 5) return 0;
    for (let i = 0; i < pistes.length; i++) {
      for (let j = 0; j < pistes[i].length - 1; j++) {
        if (segmentDistance(p, pistes[i][j], pistes[i][j + 1]) < 7) return 0;
      }
    }
    return s.slope > 0.85 ? 0.15 : 0.85;
  });
  trees.forEach(function(p) {
    const scale = 0.7 + Math.random() * 0.55;
    place('pine', p, [5 * scale, 10 * scale, 5 * scale], Math.random() * Math.PI * 2);
  });
}
